#!/usr/bin/env bash
# Build Silo's depth-fix d3d11 proxy (Proxy/d3d11-depth-fix) into the committed resource
# Sources/SiloKit/Resources/silo-depth-fix-d3d11.dll.
#
# The proxy is a Windows PE, so it needs a mingw cross-compiler — which the normal SwiftPM build (constraint
# #1: Command Line Tools alone) doesn't have. Like the app icon (Resources/AppIcon.icns, regenerated by
# Scripts/make-icon.sh), the built file is therefore COMMITTED and this script only regenerates it after the
# source changes. The toolchain is mstorsjo/llvm-mingw at LLVM_MINGW_VERSION (versions.env, the one DXMT pins),
# downloaded once into .toolchains/ (git-ignored). No Homebrew.
#
# Usage: Scripts/build-depth-proxy.sh
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
# shellcheck disable=SC1091
. "$ROOT/versions.env"

MINGW_DIR="llvm-mingw-${LLVM_MINGW_VERSION}-ucrt-macos-universal"
TOOLCHAINS="$ROOT/.toolchains"
CC="$TOOLCHAINS/$MINGW_DIR/bin/x86_64-w64-mingw32-gcc"
SRC="$ROOT/Proxy/d3d11-depth-fix"
OUT="$ROOT/Sources/SiloKit/Resources/silo-depth-fix-d3d11.dll"

if [ ! -x "$CC" ]; then
  echo "==> Fetch llvm-mingw $LLVM_MINGW_VERSION"
  mkdir -p "$TOOLCHAINS"
  curl -fL "https://github.com/mstorsjo/llvm-mingw/releases/download/${LLVM_MINGW_VERSION}/${MINGW_DIR}.tar.xz" \
    -o "$TOOLCHAINS/llvm-mingw.tar.xz"
  tar -xf "$TOOLCHAINS/llvm-mingw.tar.xz" -C "$TOOLCHAINS"
  rm "$TOOLCHAINS/llvm-mingw.tar.xz"
fi

echo "==> Build $(basename "$OUT")"
# Built as d3d11.dll (its export-table name is the output file name), then stored under the resource name.
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
"$CC" -O2 -shared -s -Wall -o "$TMP/d3d11.dll" "$SRC/proxy.c" "$SRC/proxy.def" -ldxguid
cp "$TMP/d3d11.dll" "$OUT"

# The marker Silo uses to recognise its own file in a bottle (GraphicsLinker.depthFixMarker) must survive.
grep -q "Silo depth-fix d3d11 proxy" "$OUT" || { echo "ERROR: marker missing from $OUT"; exit 1; }
echo "==> Built $OUT"
